add_action( 'admin_init', 'perfectpixel_default_featured_image_setting' );
add_action( 'admin_enqueue_scripts', 'perfectpixel_default_featured_image_media' );
add_filter( 'post_thumbnail_id', 'perfectpixel_default_featured_image_id', 20, 2 );

function perfectpixel_default_featured_image_setting() {
	register_setting( 'media', 'perfectpixel_default_featured_image', array( 'type' => 'integer', 'sanitize_callback' => 'absint', 'default' => 0 ) );
	add_settings_field( 'perfectpixel_default_featured_image', 'Προεπιλεγμένη εικόνα άρθρων', 'perfectpixel_default_featured_image_field', 'media', 'default' );
}

function perfectpixel_default_featured_image_media( $hook ) {
	if ( 'options-media.php' === $hook ) {
		wp_enqueue_media();
	}
}

function perfectpixel_default_featured_image_field() {
	$id = (int) get_option( 'perfectpixel_default_featured_image' );
	?>
	<div id="perfectpixel-default-thumb">
		<div class="perfectpixel-default-thumb-preview" style="margin-bottom:8px"><?php echo $id ? wp_get_attachment_image( $id, 'thumbnail' ) : ''; ?></div>
		<input type="hidden" name="perfectpixel_default_featured_image" class="perfectpixel-default-thumb-id" value="<?php echo esc_attr( $id ? $id : '' ); ?>">
		<button type="button" class="button perfectpixel-default-thumb-choose"><?php echo 'Επιλογή εικόνας'; ?></button>
		<button type="button" class="button-link perfectpixel-default-thumb-remove" style="margin-left:8px<?php echo $id ? '' : ';display:none'; ?>"><?php echo 'Αφαίρεση'; ?></button>
	</div>
	<script>
	( function () {
		var box = document.getElementById( 'perfectpixel-default-thumb' );
		if ( ! box || ! window.wp || ! wp.media ) {
			return;
		}
		var input = box.querySelector( '.perfectpixel-default-thumb-id' );
		var preview = box.querySelector( '.perfectpixel-default-thumb-preview' );
		var remove = box.querySelector( '.perfectpixel-default-thumb-remove' );
		var frame;
		box.querySelector( '.perfectpixel-default-thumb-choose' ).addEventListener( 'click', function () {
			frame = frame || wp.media( { library: { type: 'image' }, multiple: false } );
			frame.off( 'select' ).on( 'select', function () {
				var img = frame.state().get( 'selection' ).first().toJSON();
				input.value = img.id;
				preview.innerHTML = '';
				var el = document.createElement( 'img' );
				el.src = ( img.sizes && img.sizes.thumbnail ) ? img.sizes.thumbnail.url : img.url;
				el.style.maxWidth = '150px';
				el.style.height = 'auto';
				preview.appendChild( el );
				remove.style.display = '';
			} );
			frame.open();
		} );
		remove.addEventListener( 'click', function () {
			input.value = '';
			preview.innerHTML = '';
			remove.style.display = 'none';
		} );
	} )();
	</script>
	<?php
}

// Front end only, so the editor still shows which posts have no image of their own.
function perfectpixel_default_featured_image_id( $thumbnail_id, $post ) {
	if ( $thumbnail_id || is_admin() || ! $post || 'post' !== get_post_type( $post ) ) {
		return $thumbnail_id;
	}
	$default = (int) get_option( 'perfectpixel_default_featured_image' );
	return ( $default && wp_attachment_is_image( $default ) ) ? $default : $thumbnail_id;
}
